----------------------------------------------------------------------
-- 2. TEMP TABLE: Category counts, exceeded indicator, total max cols
----------------------------------------------------------------------
CREATE OR REPLACE TEMPORARY TABLE gbi_fraud_bap_db.ai_live_biz_app.trader_tfa_ww_priority AS (
    SELECT
        b.* EXCLUDE (category_filled),

        CASE
            WHEN category.KEY != '_dummy' AND (
                TRIM(SPLIT(GET_PATH(session_cookie.item_count, category.KEY)::STRING, ',')[1]) = 'Y' OR
                TRIM(SPLIT(GET_PATH(b2_em.item_count,         category.KEY)::STRING, ',')[1]) = 'Y' OR
                TRIM(SPLIT(GET_PATH(a1_em.item_count,         category.KEY)::STRING, ',')[1]) = 'Y' OR
                TRIM(SPLIT(GET_PATH(guid.item_count,          category.KEY)::STRING, ',')[1]) = 'Y' OR
                TRIM(SPLIT(GET_PATH(dsid.item_count,          category.KEY)::STRING, ',')[1]) = 'Y' OR
                TRIM(SPLIT(GET_PATH(card_hash.item_count,     category.KEY)::STRING, ',')[1]) = 'Y' OR
                TRIM(SPLIT(GET_PATH(payment_id.item_count,    category.KEY)::STRING, ',')[1]) = 'Y' OR
                TRIM(SPLIT(GET_PATH(student_id.item_count,    category.KEY)::STRING, ',')[1]) = 'Y'
            )
            THEN 'Y' ELSE 'N'
        END AS exceeded_ind,

        GREATEST(
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(session_cookie.item_count, 'V57_202509'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(b2_em.item_count,         'V57_202509'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(a1_em.item_count,         'V57_202509'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(guid.item_count,          'V57_202509'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(dsid.item_count,          'V57_202509'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(card_hash.item_count,     'V57_202509'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(payment_id.item_count,    'V57_202509'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(student_id.item_count,    'V57_202509'), ',', 1)) AS INTEGER),0)
        ) AS V57_202509_total_max,

        GREATEST(
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(session_cookie.item_count, 'V54_202509'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(b2_em.item_count,         'V54_202509'), ',', 1)) AS INTEGER),0),
