            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(session_cookie.item_count, 'N230_202509'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(b2_em.item_count,         'N230_202509'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(a1_em.item_count,         'N230_202509'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(guid.item_count,          'N230_202509'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(dsid.item_count,          'N230_202509'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(card_hash.item_count,     'N230_202509'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(payment_id.item_count,    'N230_202509'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(student_id.item_count,    'N230_202509'), ',', 1)) AS INTEGER),0)
        ) AS N230_202509_total_max,

        GREATEST(
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(session_cookie.item_count, 'D23_202509'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(b2_em.item_count,         'D23_202509'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(a1_em.item_count,         'D23_202509'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(guid.item_count,          'D23_202509'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(dsid.item_count,          'D23_202509'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(card_hash.item_count,     'D23_202509'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(payment_id.item_count,    'D23_202509'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(student_id.item_count,    'D23_202509'), ',', 1)) AS INTEGER),0)
        ) AS D23_202509_total_max,

        GREATEST(
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(session_cookie.item_count, 'edu_mac'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(b2_em.item_count,         'edu_mac'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(a1_em.item_count,         'edu_mac'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(guid.item_count,          'edu_mac'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(dsid.item_count,          'edu_mac'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(card_hash.item_count,     'edu_mac'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(payment_id.item_count,    'edu_mac'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(student_id.item_count,    'edu_mac'), ',', 1)) AS INTEGER),0)
        ) AS edu_mac_total_max,

        GREATEST(
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(session_cookie.item_count, 'edu_ipad'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(b2_em.item_count,         'edu_ipad'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(a1_em.item_count,         'edu_ipad'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(guid.item_count,          'edu_ipad'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(dsid.item_count,          'edu_ipad'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(card_hash.item_count,     'edu_ipad'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(payment_id.item_count,    'edu_ipad'), ',', 1)) AS INTEGER),0),
            COALESCE(CAST(TRIM(SPLIT_PART(GET_PATH(student_id.item_count,    'edu_ipad'), ',', 1)) AS INTEGER),0)
        ) AS edu_ipad_total_max,

        session_cookie.item_count AS session_cookie_item_count,
        b2_em.item_count          AS b2_em_item_count,
        a1_em.item_count          AS a1_em_item_count,
        guid.item_count           AS guid_item_count,
        dsid.item_count           AS dsid_item_count,
        card_hash.item_count      AS card_hash_item_count,
        payment_id.item_count     AS payment_id_item_count,
        student_id.item_count     AS student_id_item_count,
        b2_ph.item_count          AS b2_ph_item_count,
        ip_add.item_count         AS ip_add_item_count

    FROM gbi_fraud_bap_db.ai_live_biz_app.trader_tfa_ww_priority_temp b

    LEFT JOIN gbi_fraud_bap_db.ai_live_biz_app.trader_tfa_session_cookie_category_counts session_cookie
        ON b.sales_org = session_cookie.sales_org AND b.session_cookie = session_cookie.session_cookie
    LEFT JOIN gbi_fraud_bap_db.ai_live_biz_app.trader_tfa_b2_em_category_counts b2_em
        ON b.sales_org = b2_em.sales_org AND b.b2_em = b2_em.b2_em
    LEFT JOIN gbi_fraud_bap_db.ai_live_biz_app.trader_tfa_a1_em_category_counts a1_em
        ON b.sales_org = a1_em.sales_org AND b.a1_em = a1_em.a1_em
    LEFT JOIN gbi_fraud_bap_db.ai_live_biz_app.trader_tfa_guid_category_counts guid
        ON b.sales_org = guid.sales_org AND b.guid = guid.guid
    LEFT JOIN gbi_fraud_bap_db.ai_live_biz_app.trader_tfa_dsid_category_counts dsid
        ON b.sales_org = dsid.sales_org AND b.dsid = dsid.dsid
    LEFT JOIN gbi_fraud_bap_db.ai_live_biz_app.trader_tfa_card_hash_category_counts card_hash
        ON b.sales_org = card_hash.sales_org AND b.card_hash = card_hash.card_hash
    LEFT JOIN gbi_fraud_bap_db.ai_live_biz_app.trader_tfa_payment_id_category_counts payment_id
        ON b.sales_org = payment_id.sales_org AND b.payment_id = payment_id.payment_id
    LEFT JOIN gbi_fraud_bap_db.ai_live_biz_app.trader_tfa_student_id_category_counts student_id
        ON b.sales_org = student_id.sales_org AND b.student_id = student_id.student_id
    LEFT JOIN gbi_fraud_bap_db.ai_live_biz_app.trader_tfa_b2_ph_category_counts b2_ph
        ON b.sales_org = b2_ph.sales_org AND b.b2_ph = b2_ph.b2_ph
    LEFT JOIN gbi_fraud_bap_db.ai_live_biz_app.trader_tfa_ip_add_category_counts ip_add
        ON b.sales_org = ip_add.sales_org AND b.ip_add = ip_add.ip_add
    LEFT JOIN LATERAL FLATTEN(input => b.category_filled) AS category

    QUALIFY ROW_NUMBER() OVER (PARTITION BY b.order_id ORDER BY exceeded_ind DESC NULLS LAST) = 1
);


----------------------------------------------------------------------
-- 3. FINAL SELECT: Enrich with OOCA, velocity cluster, product counts
----------------------------------------------------------------------
WITH flattened_data AS (
    SELECT
        twmr.order_id,
        MAX(CASE WHEN f.key ILIKE '%V53%' THEN SPLIT_PART(f.value::STRING, ',', 1)::INTEGER END) AS v53_product_code_count,
        MAX(CASE WHEN f.key ILIKE '%V54%' THEN SPLIT_PART(f.value::STRING, ',', 1)::INTEGER END) AS v54_product_code_count,
        MAX(CASE WHEN f.key ILIKE '%V57%' THEN SPLIT_PART(f.value::STRING, ',', 1)::INTEGER END) AS v57_product_code_count
    FROM gbi_fraud_bap_db.ai_live_biz_app.trader_tfa_ww_priority twmr,
         LATERAL FLATTEN(input => twmr.IP_ADD_ITEM_COUNT) f
    GROUP BY twmr.order_id
)
SELECT
    twmr.*,
    velo_test.*,
    CAST(twmr.OOCA:activated_countries            AS INTEGER) AS activated_countries,
    CAST(twmr.OOCA:activated_serials              AS INTEGER) AS activated_serials,
    CAST(twmr.OOCA:out_of_country_activation_rate AS FLOAT)   AS out_of_country_activation_rate,
    fd.v53_product_code_count,
    fd.v54_product_code_count,
    fd.v57_product_code_count
FROM gbi_fraud_bap_db.ai_live_biz_app.trader_tfa_ww_priority twmr
LEFT JOIN flattened_data fd
    ON fd.order_id = twmr.order_id
LEFT JOIN gbi_fraud_bap_db.ai_live_biz_app.TRADER_TFA_A1ADD_VELOCITY_CLUSTER_RELAXED_TEST velo_test
    ON velo_test.web_order_id = twmr.web_order_id;